import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        print("not possible")
        return

    n = int(data[0])
    start_floor = int(data[1])

    if n + 1 >= len(data):
        arr = list(map(int, data[2:2+n]))
    else:
        print("not possible")
        return

    if n == 0:
        print("not possible")
        return

    arr.sort()

    current = start_floor

    for i in range(n):
        if i % 2 == 0:
            current -= arr[i]
        else:
            current += arr[i]

        if current < 1:
            current = 1

    if current != start_floor:
        print(' '.join(map(str, arr)))
    else:
        print("not possible")

if __name__ == "__main__":
    solve()
